describe('Accessible Loading States', () => {
  beforeEach(() => {
    cy.visit('/loading-states');
  });

  it('should display appropriate ARIA roles and properties during loading', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/data').as('dataLoad');

    // Verify initial state has no content and loading indicators
    cy.get('[data-testid="loading-indicator"]').should('be.visible');
    cy.get('[data-testid="content-area"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify ARIA attributes are present
    cy.get('[data-testid="loading-indicator"]').should('have.attr', 'aria-busy', 'true');
    cy.get('[data-testid="loading-indicator"]').should('have.attr', 'aria-label', 'Loading...');

    // Trigger the API call
    cy.wait('@dataLoad');

    // Verify loading state is removed and content is displayed
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="content-area"]').should('be.visible');
    cy.get('[data-testid="content-area"]').should('contain', 'Data loaded successfully');

    // Verify ARIA attributes are updated
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="content-area"]').should('have.attr', 'aria-busy', 'false');
    cy.get('[data-testid="content-area"]').should('have.attr', 'aria-live', 'polite');
  });

  it('should handle loading states when API fails', () => {
    // Intercept the API call with a 500 error
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('dataLoadError');

    // Verify initial state is visible
    cy.get('[data-testid="loading-indicator"]').should('be.visible');
    cy.get('[data-testid="content-area"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Trigger the API call
    cy.wait('@dataLoadError');

    // Verify error state is displayed
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify ARIA attributes are set for error state
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'assertive');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-describedby', 'error-details');

    // Verify error details are displayed
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Error code: 500');
  });
});
